const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'}});
const uuid=()=>crypto.randomUUID();
const safeWebUrl=value=>{try{const u=new URL(String(value||''));return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}};
const iso=()=>new Date().toISOString();
const emailKey=v=>String(v||'').trim().toLowerCase();
const phoneKey=v=>String(v||'').replace(/\D/g,'');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bodyLimit=async(req,max=30000)=>{const n=Number(req.headers.get('content-length')||0);if(n>max)throw Object.assign(new Error('Solicitare prea mare.'),{status:413});const raw=await req.text();if(raw.length>max)throw Object.assign(new Error('Solicitare prea mare.'),{status:413});try{return JSON.parse(raw)}catch{throw Object.assign(new Error('Date JSON invalide.'),{status:400})}};
const validStatus=new Set(['new','reviewing','quote_sent','confirmed','in_production','completed','cancelled']);
const toCents=v=>v===null||v===''||v===undefined?null:(Number.isFinite(Number(v))&&Number(v)>=0?Math.round(Number(v)*100):NaN);

async function mergeCustomerSubmission(db,id,{phone,billing}){
 const old=await db.prepare('SELECT billing_json FROM customers WHERE id=?').bind(id).first();let current={};try{current=JSON.parse(old?.billing_json||'{}')}catch{}
 const incoming=billing&&typeof billing==='object'&&!Array.isArray(billing)?billing:{};
 const merged={...current,...Object.fromEntries(Object.entries(incoming).filter(([,v])=>v!==''&&v!==null&&v!==undefined))};
 await db.prepare("UPDATE customers SET phone=CASE WHEN phone IS NULL OR phone='' THEN ? ELSE phone END,billing_json=?,updated_at=? WHERE id=?").bind(phone||null,JSON.stringify(merged),iso(),id).run();
}
async function matchOrCreateCustomer(db,{name,email,phone,billing}){
 const e=emailKey(email),p=phoneKey(phone),now=iso();
 if(e){const found=await db.prepare("SELECT customer_id FROM customer_identifiers WHERE kind='email' AND normalized_value=?").bind(e).first();if(found){await mergeCustomerSubmission(db,found.customer_id,{phone,billing});return found.customer_id}}
 // A phone match is automatic only when no email was supplied and the number
 // resolves to one customer. Shared numbers and changed emails are not merged.
 if(!e&&p){const found=await db.prepare("SELECT customer_id FROM customer_identifiers WHERE kind='phone' AND normalized_value=? LIMIT 2").bind(p).all();if(found.results?.length===1){await mergeCustomerSubmission(db,found.results[0].customer_id,{phone,billing});return found.results[0].customer_id}}
 const id=uuid();
 const statements=[db.prepare('INSERT INTO customers(id,display_name,email,phone,billing_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?)').bind(id,name,email||null,phone||null,JSON.stringify(billing||{}),now,now)];
 if(e)statements.push(db.prepare("INSERT INTO customer_identifiers(customer_id,kind,normalized_value,created_at) VALUES(?,'email',?,?)").bind(id,e,now));
 if(p)statements.push(db.prepare("INSERT INTO customer_identifiers(customer_id,kind,normalized_value,created_at) VALUES(?,'phone',?,?)").bind(id,p,now));
 try{await db.batch(statements);return id}catch(error){if(e){const found=await db.prepare("SELECT customer_id FROM customer_identifiers WHERE kind='email' AND normalized_value=?").bind(e).first();if(found)return found.customer_id}throw error}
}

function numberFor(now){const date=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Bucharest',year:'numeric',month:'2-digit',day:'2-digit'}).format(now).replaceAll('-','');return `WL-${date}-${crypto.randomUUID().replaceAll('-','').slice(0,10).toUpperCase()}`;}
function detailsFromMessage(type,message,details){
 if(details&&typeof details==='object')return details;
 if(type==='dtf'){
  const line=(label)=>{const m=String(message||'').match(new RegExp('^'+label+'\\s*:\\s*(.*)$','im'));return m?m[1].trim():''};
  return {rollWidth:line('Lățime rolă'),orderedLength:line('Cantitate'),artworkLink:line('Link fișiere grafice'),observations:line('Observații'),billingText:String(message||'').split(/DATE DE FACTURARE/i)[1]?.trim()||''};
 }
 const chunks=String(message||'').split(/--- Serviciul \d+ ---/).slice(1).map(x=>x.trim()).filter(Boolean);
 return {services:chunks,additionalDetails:String(message||'').split(/Detalii despre proiect:/i)[1]?.trim()||'',sourceMessage:String(message||'')};
}

async function submitOrder(request,env,ctx){
 const reply=(o,s=200)=>new Response(JSON.stringify(o),{status:s,headers:{'Access-Control-Allow-Origin':'https://waknolab.com','Vary':'Origin','Cache-Control':'no-store','Content-Type':'application/json; charset=utf-8'}});
 if(env.DB){const ip=request.headers.get('CF-Connecting-IP')||'unknown';const raw=new TextEncoder().encode(String(env.GITHUB_CLIENT_SECRET||'wakno-rate-limit')+':'+ip);const digest=await crypto.subtle.digest('SHA-256',raw);const bucket=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,32);const now=Math.floor(Date.now()/1000),windowStart=now-now%60;const hit=await env.DB.prepare("INSERT INTO request_rate_limits(bucket_key,window_start,request_count) VALUES(?,?,1) ON CONFLICT(bucket_key) DO UPDATE SET window_start=CASE WHEN request_rate_limits.window_start < ? THEN ? ELSE request_rate_limits.window_start END, request_count=CASE WHEN request_rate_limits.window_start < ? THEN 1 ELSE request_rate_limits.request_count+1 END RETURNING request_count").bind(bucket,windowStart,windowStart,windowStart,windowStart).first();if((hit?.request_count||0)>5)return reply({error:'Prea multe solicitări. Așteaptă un minut și încearcă din nou.'},429)}
 if(request.headers.get('Origin')!=='https://waknolab.com')return reply({error:'Origine neautorizată.'},403);
 if(!env.DB)return reply({error:'Salvarea comenzilor nu este configurată.'},503);
 
 if(!/^application\/json\b/i.test(request.headers.get('content-type')||''))return reply({error:'Format invalid.'},415);
 let d;try{d=await bodyLimit(request,25000)}catch(e){return reply({error:e.message},e.status||400)}
 if(!d||typeof d!=='object'||d.website)return reply({error:'Solicitare invalidă.'},400);
 const clean=(x,n)=>typeof x==='string'?x.trim().slice(0,n):'';
 const name=clean(d.name,120),email=clean(d.email,254),phone=clean(d.phone,40),subject=clean(d.subject,160),message=clean(d.message,17000);
 const submissionId=/^[a-f0-9-]{36}$/i.test(d.submissionId||'')?d.submissionId:uuid();
 if(name.length<2||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||phoneKey(phone).length<9||!subject||message.length<20)return reply({error:'Verifică datele formularului.'},400);
 if(d.submissionId){const existing=await env.DB.prepare('SELECT order_number FROM orders WHERE submission_id=?').bind(submissionId).first();if(existing)return reply({ok:true,orderNumber:existing.order_number,duplicate:true});}
 const dtf=subject.startsWith('WAKNO LABS | SERVICIU PRINT DTF'),type=dtf?'dtf':'service_quote',now=iso(),id=uuid(),orderNumber=numberFor(new Date()),details=detailsFromMessage(type,message,d.details),artworkLinks=(Array.isArray(details.artworkLinks)?details.artworkLinks:[details.artworkLink]).map(safeWebUrl).filter(Boolean).slice(0,10);
 let billing={};if(dtf&&details.billing&&typeof details.billing==='object')billing=details.billing;else if(dtf&&details.billingText)billing={raw:details.billingText};
 let customerId;
 try{customerId=await matchOrCreateCustomer(env.DB,{name,email,phone,billing});}catch(e){if(email){const found=await env.DB.prepare("SELECT customer_id FROM customer_identifiers WHERE kind='email' AND normalized_value=?").bind(emailKey(email)).first();if(found)customerId=found.customer_id;}if(!customerId)return reply({error:'Nu am putut salva datele clientului. Reîncearcă.'},503)}
 const adminTo=env.ORDER_NOTIFICATION_EMAIL||'waknolab@gmail.com';
 try{
  const statements=[
   env.DB.prepare('INSERT INTO orders(id,order_number,submission_id,order_type,customer_id,status,submitted_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)').bind(id,orderNumber,submissionId,type,customerId,'new',now,now,now),
   type==='dtf'
    ?env.DB.prepare('INSERT INTO dtf_order_details(order_id,roll_width_cm,ordered_length_m,quantity,artwork_links_json,billing_json,observations,source_message) VALUES(?,?,?,?,?,?,?,?)').bind(id,Number(details.rollWidthCm??details.rollWidth)||null,Number(details.orderedLengthM??details.quantityMeters)||null,Number(details.quantity)||null,JSON.stringify(artworkLinks),JSON.stringify(billing),String(details.observations||''),message)
    :env.DB.prepare('INSERT INTO service_order_details(order_id,services_json,additional_details,source_message) VALUES(?,?,?,?)').bind(id,JSON.stringify(details.services||[]),String(details.additionalDetails||''),message),
   env.DB.prepare('INSERT INTO order_events(id,order_id,actor,event_type,new_value_json,created_at) VALUES(?,?,?,?,?,?)').bind(uuid(),id,'system','order_created',JSON.stringify({status:'new',orderType:type}),now),
   env.DB.prepare('INSERT INTO email_outbox(id,order_id,email_kind,recipient,idempotency_key,status,attempts,next_attempt_at,created_at) VALUES(?,?,?,?,?,?,?,?,?)').bind(uuid(),id,'admin_notification',adminTo,`order-admin/${submissionId}`,'pending',0,now,now),
   env.DB.prepare('INSERT INTO email_outbox(id,order_id,email_kind,recipient,idempotency_key,status,attempts,next_attempt_at,created_at) VALUES(?,?,?,?,?,?,?,?,?)').bind(uuid(),id,'customer_confirmation',email,`order-customer/${submissionId}`,'pending',0,now,now)
  ];
  await env.DB.batch(statements);
 }catch(e){const existing=await env.DB.prepare('SELECT order_number FROM orders WHERE submission_id=?').bind(submissionId).first();if(existing)return reply({ok:true,orderNumber:existing.order_number,duplicate:true});console.error('Order persistence failed');return reply({error:'Nu am putut înregistra comanda. Datele nu au fost confirmate; te rugăm să reîncerci.'},503)}
 if(ctx?.waitUntil)ctx.waitUntil(dispatchOutbox(env));else await dispatchOutbox(env);
 return reply({ok:true,orderNumber});
}

async function scheduledMaintenance(env){await dispatchOutbox(env);if(env.DB)await env.DB.prepare('DELETE FROM request_rate_limits WHERE window_start<?').bind(Math.floor(Date.now()/1000)-7200).run()}

